from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

import heapq
import itertools


def _route(data, coupon_rule, minimum_duration):
    required = data.get("required", [])
    full_mask = (1 << len(required)) - 1
    required_bits = {}
    for i, node in enumerate(required):
        required_bits[node] = required_bits.get(node, 0) | (1 << i)

    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = required_bits.get(source, 0)
    initial_used = 0
    initial_time = data["start"]
    start_state = (source, initial_mask, initial_used)
    distances = {start_state: initial_time}
    queue = [(initial_time, source, initial_mask, initial_used)]
    coupons = data["coupons"]
    deadline = data["deadline"]

    while queue:
        arrival, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if distances.get(state) != arrival:
            continue
        if (node == data["target"] and mask == full_mask
                and (coupon_rule == "at_most" or used == coupons)):
            return {"arrival": arrival}

        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < coupons:
                discounted = max(minimum_duration,
                                 edge["duration"] - edge.get("discount", 0))
                options.append((discounted, used + 1))
            for duration, next_used in options:
                next_time = depart + duration
                if next_time > deadline:
                    continue
                next_node = edge["v"]
                next_mask = mask | required_bits.get(next_node, 0)
                next_state = (next_node, next_mask, next_used)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue,
                                   (next_time, next_node, next_mask, next_used))
    return {"arrival": None}


def _component_01(data):
    return _route(data, "at_most", 2)


def _component_02(data):
    return _route(data, "exact", 2)


def _component_03(data):
    return _route(data, "at_most", 1)


def _component_04(data):
    return _route(data, "exact", 1)


def _component_05(data):
    return _route(data, "at_most", 2)


def _round(numerator, denominator, mode):
    if mode == "half_up":
        return (numerator + denominator // 2) // denominator
    return numerator // denominator


def _component_06(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), 10000, mode)
        tax = _round(raw * event.get("tax_bp", 0), 10000, mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = account + "|" + currency
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_07(data):
    packages = data["packages"]
    names = list(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]

    # Enumerate absent or installed versions; the small published bounds make
    # exhaustive search straightforward and allow all interacting constraints.
    choices = []
    for name in names:
        versions = sorted(row["version"] for row in packages[name])
        choices.append([-1] + versions)

    best_vector = None
    best_installation = None
    for values in itertools.product(*choices):
        assignment = dict(zip(names, values))
        if any(assignment.get(name, -1) < bounds[0]
               or assignment.get(name, -1) > bounds[1]
               for name, bounds in roots.items()):
            continue
        if any(version != -1 and name in pins and version != pins[name]
               for name, version in assignment.items()):
            continue
        if any(version in blocked.get(name, [])
               for name, version in assignment.items() if version != -1):
            continue

        rows_by_name = {}
        for name, version in assignment.items():
            if version != -1:
                rows_by_name[name] = next(
                    row for row in packages[name] if row["version"] == version)

        graph = {name: [] for name in rows_by_name}
        valid = True
        for name, row in rows_by_name.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                dep_name = dep["name"]
                dep_version = assignment.get(dep_name, -1)
                if dep_version == -1 or not dep["min"] <= dep_version <= dep["max"]:
                    valid = False
                    break
                graph[name].append(dep_name)
            if not valid:
                break
        if not valid:
            continue

        # Installed packages must be precisely the closure of the roots.
        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            if name not in rows_by_name:
                valid = False
                break
            reachable.add(name)
            stack.extend(graph[name])
        if not valid or reachable != set(rows_by_name):
            continue

        finished = set()
        active = set()

        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            for child in graph[name]:
                if not visit(child):
                    return False
            active.remove(name)
            finished.add(name)
            return True

        if any(not visit(name) for name in graph):
            continue

        vector = tuple(assignment[name] for name in sorted(names, reverse=True))
        if best_vector is None or vector < best_vector:
            best_vector = vector
            best_installation = {name: version for name, version in assignment.items()
                                  if version != -1}

    if best_installation is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_installation}


def _component_08(data):
    jobs = data["jobs"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    k = data["k"]
    candidates = [job for job in jobs if job["id"] not in blocked]

    best_value = None
    best_ids = None
    for subset in itertools.combinations(candidates, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue

        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        ordered = sorted(subset, key=lambda job: (job["start"], job["end"], job["id"]))
        if any(ordered[i - 1]["end"] > ordered[i]["start"]
               for i in range(1, len(ordered))):
            continue

        selected = sorted(ids)
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value
                or (value == best_value and selected < best_ids)):
            best_value = value
            best_ids = selected

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


SOLVERS = {
    "component_01": _component_01,
    "component_02": _component_02,
    "component_03": _component_03,
    "component_04": _component_04,
    "component_05": _component_05,
    "component_06": _component_06,
    "component_07": _component_07,
    "component_08": _component_08,
}
